import {getAction} from '@madou/catalog';
import {createGame,gameStats,transition,allCardInstanceIds,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const dragonKingCard='a2-p09-r2c2';
export const dragonKingMaai=['a2-p06-r1c3','a2-p06-r2c1','a2-p06-r2c2','a2-p06-r2c3','a2-p06-r3c1'] as const;
export const dragonKingScenarios=['dragon-king-ordinary','dragon-king-owner-ordinary','dragon-king-low','dragon-king-dedicated','dragon-king-pair','dragon-king-all','dragon-king-near','dragon-king-same-faction','dragon-king-water-ordinary','dragon-king-water','dragon-king-maai-ordinary','dragon-king-maai-full','dragon-king-maai-short','dragon-king-evade-ordinary','dragon-king-evade-dedicated','dragon-king-fate','dragon-king-suppressed','dragon-king-silenced','dragon-king-stopped','dragon-king-wrong-owner','dragon-king-decline','dragon-king-noncounter','dragon-king-resistance-fail','dragon-king-reroll'] as const;
export type DragonKingScenario=typeof dragonKingScenarios[number];
export function isDragonKingScenario(name:string):name is DragonKingScenario{return (dragonKingScenarios as readonly string[]).includes(name);}
export function dragonKingMode(name:DragonKingScenario){const suffix=name.replace('dragon-king-',''),dedicated=!['ordinary','owner-ordinary','low','evade-ordinary','water-ordinary','maai-ordinary','decline'].includes(suffix),owner=dedicated&&suffix!=='wrong-owner'||suffix==='owner-ordinary',water=suffix.startsWith('water'),targets=suffix==='all'?[1,2,3]:suffix==='same-faction'?[1,3]:['pair','maai-full','maai-short','suppressed','silenced','resistance-fail','reroll'].includes(suffix)?[1,2]:[1];return {suffix,dedicated,owner,water,targets};}
export function makeDragonKingPhysical(name:DragonKingScenario,players:{id:string;name:string}[],options:{beforeStart?:boolean;warrior?:number;spirit?:number;targetSpirit?:number}={}){
 const m=dragonKingMode(name),prior=['suppressed','stopped','silenced'].includes(m.suffix),incoming=m.suffix==='noncounter';let s=createGame(players,entropy(),{startingSeat:prior?3:incoming?1:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];
 for(const [i,p] of players.entries())assignCharacter(s,p.id,[m.owner?'魔導王ガイナス':'侍大将のシン',m.owner?'侍大将のシン':'獣使いのウパニシャット','黒妖精のアーネス','聖騎士ランスロット'][i]!);
 for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit!+=(p.id===a?options.spirit??6:p.id===b?options.targetSpirit??6:p.id===c?12:6)-gameStats(s,p.id).spirit;}
 s.players[a]!.permanent!.warrior_level!+=(options.warrior??(m.suffix==='low'?7:m.dedicated?0:8))-gameStats(s,a).warrior_level;
 const keep=[takeCard(s,a,dragonKingCard),takeCard(s,d,'a2-p02-r2c3')];if(m.water)keep.push(takeCard(s,b,'a2-p23-r1c1'));
 if(m.suffix==='near')keep.push(takeCard(s,a,'a2-p24-r1c3'));if(m.suffix.startsWith('maai'))for(const id of dragonKingMaai)keep.push(takeCard(s,b,id));if(m.suffix.startsWith('evade'))keep.push(takeCard(s,b,'a2-p05-r3c1'));if(m.suffix==='reroll')keep.push(takeCard(s,c,'a2-p02-r1c3'));if(incoming)keep.push(takeCard(s,b,'a2-p24-r1c2'));if(prior)keep.push(takeCard(s,d,m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1'));
 for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];s.events=[];
 function act(actorId:string,command:GameCommand,face=1){const input={actorId,command},e={...entropy(),dice:Array(100).fill(face)},r=transition(s,input,e);if(!r.ok)throw Error(`DRAGON_KING_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('DRAGON_KING_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('DRAGON_KING_FIXTURE_CARDS');}
 function settle(face=1){for(let n=0;n<600;n++){const w=s.windows?.at(-1);if(!w)return;act(w.participants[w.cursor]!,{type:'PASS'},face);}throw Error('DRAGON_KING_FIXTURE_LIMIT');}
 for(const id of [a,b,c,d]){if(m.water&&id===b)act(b,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:'a2-p23-r1c1'});act(id,{type:'PASS_SETUP'});}readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));if(options.beforeStart)return s;
 if(prior){act(d,{type:'START_TURN'});settle();act(d,{type:'CHOOSE_DRAW',draw:false});act(d,{type:'ATTACK',cardInstanceId:m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1',targetIds:[a],dedicated:false});settle(6);if(s.phase==='withdrawal')act(d,{type:'PASS_WITHDRAWAL'});act(d,{type:'END_TURN',discardIds:[]});settle();}
 const starter=incoming?b:a;act(starter,{type:'START_TURN'});settle(prior?6:1);if(s.phase==='draw')act(starter,{type:'CHOOSE_DRAW',draw:false});if(incoming){act(b,{type:'ATTACK',cardInstanceId:'a2-p24-r1c2',targetIds:[a],dedicated:false});for(let n=0;n<400;n++){const w=s.windows!.at(-1)!;if(w.kind==='normal-defense')return s;act(w.participants[w.cursor]!,{type:'PASS'});}throw Error('DRAGON_KING_FIXTURE_COUNTER_LIMIT');}
 if(m.suffix==='near'){act(a,{type:'APPROACH',cardInstanceId:'a2-p24-r1c3',targetId:b});settle();}if(m.suffix==='same-faction'){act(c,{type:'REVEAL_CHARACTER'});settle();}return s;
}
